<script setup lang="ts">
// Author by Lab | zefry
import { computed, reactive, ref } from 'vue';
import { Head, router } from '@inertiajs/vue3';
import Icon from '../../components/WorkspaceIcon.vue';
import { locale } from '../../i18n';
type Logo={width:number;height:number;bits:string};
type Kitchen={id:string;name:string;categories:string[]};
type Preferences={show_logo:boolean;logo:Logo|null;footer:string;auto_lock_seconds:number;report_recipients:string[];kitchens:Kitchen[]};
type Cashier={login:string;name:string;enabled:boolean;version:number;identity_id:string};
const props=defineProps<{version:number;settings:Preferences;cashiers:Cashier[];owner_account?:{login:string;name:string;identity_id:string}|null;closures:{operation_id:string;report:{shift_id:string;cashier:string;expected:number;counted:number;variance:number;currency:string;scale:number};mail_queued:number}[]}>();
const tr=(id:string,en:string)=>locale.value==='id'?id:en;
const form=reactive<Preferences>(JSON.parse(JSON.stringify(props.settings)));const version=ref(props.version);const tab=ref('receipt');const busy=ref(false);const error=ref('');const success=ref('');const recipients=ref(form.report_recipients.join('\n'));const editor=ref(false);
const blank=()=>({account_type:'staff',login:'',name:'',password:'',pin:'',enabled:true,version:0,operation_id:crypto.randomUUID()});const cashier=reactive(blank());
const tabs=computed(()=>[{id:'receipt',name:tr('Struk pelanggan','Customer receipts'),icon:'receipt-text'},{id:'cashiers',name:tr('Akun kasir','Cashier accounts'),icon:'users'},{id:'operations',name:tr('Shift & keamanan','Shifts & security'),icon:'shield-check'},{id:'kitchens',name:tr('Dapur & routing','Kitchens & routing'),icon:'printer'}]);
async function post(path:string,data:unknown){const csrf=document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content??'';const response=await fetch(path,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify(data),signal:AbortSignal.timeout(25000)});if(response.status===401||response.status===419){location.assign('/login');throw Error('SESSION_EXPIRED')}const body=await response.json();if(body.code==='OWNER_EMAIL_USE_EXISTING_ACCOUNT')throw Error(tr('Email ini adalah akun owner. Pilih Gunakan akun owner saya untuk mengaktifkan akses kasir.','This is the owner email. Choose Use my owner account to enable cashier access.'));if(!response.ok)throw Error(`${body.code??body.message??'POS_SETTINGS_FAILED'} · ${body.correlation_id??response.status}`);return body;}
async function save(){if(busy.value)return;busy.value=true;error.value='';success.value='';try{form.report_recipients=recipients.value.split(/[\n,;]/).map(s=>s.trim()).filter(Boolean);const result=await post('/pos/business/desktop',{version:version.value,settings:form});version.value=result.version;success.value=tr('Pengaturan tersimpan. Kasir menerima perubahan saat tersambung kembali.','Settings saved. Cashiers receive changes when they reconnect.')}catch(e){error.value=String(e)}finally{busy.value=false}}
function edit(row?:Cashier){Object.assign(cashier,blank(),row??{});cashier.enabled=Boolean(cashier.enabled);if(row?.identity_id===props.owner_account?.identity_id)cashier.account_type='owner';editor.value=true;error.value=''}
function editOwner(){const owner=props.owner_account;if(!owner)return;const existing=props.cashiers.find(c=>c.identity_id===owner.identity_id);edit(existing);Object.assign(cashier,{account_type:'owner',login:owner.login,name:existing?.name??owner.name,password:''});}
async function saveCashier(){if(busy.value)return;busy.value=true;error.value='';try{const {identity_id:_,...data}=cashier as typeof cashier & {identity_id?:string};await post('/pos/business/desktop/cashiers',data);cashier.password='';cashier.pin='';editor.value=false;router.reload({only:['cashiers']});success.value=tr('Akun kasir tersimpan.','Cashier account saved.')}catch(e){error.value=String(e)}finally{busy.value=false}}
async function finalize(id:string){if(busy.value)return;busy.value=true;error.value='';try{await post('/pos/business/desktop/finalize',{operation_id:id});router.reload({only:['closures']});success.value=tr('Penutupan disahkan. Laporan masuk antrean email.','Closure finalized. Reports queued for email.')}catch(e){error.value=String(e)}finally{busy.value=false}}
function logoUrl(logo:Logo|null){if(!logo)return '';const canvas=document.createElement('canvas');canvas.width=logo.width;canvas.height=logo.height;const ctx=canvas.getContext('2d')!;const raw=atob(logo.bits);const image=ctx.createImageData(logo.width,logo.height);for(let i=0;i<logo.width*logo.height;i++){const color=(raw.charCodeAt(Math.floor(i/8))&(128>>(i%8)))?0:255;image.data.set([color,color,color,255],i*4)}ctx.putImageData(image,0,0);return canvas.toDataURL('image/png')}
const preview=computed(()=>logoUrl(form.logo));
async function upload(event:Event){error.value='';try{const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024)throw Error(tr('Pilih PNG, JPG, atau WebP maksimal 2 MB.','Choose a PNG, JPG, or WebP up to 2 MB.'));const image=await createImageBitmap(file);if(image.width>10000||image.height>10000){image.close();throw Error('POS_LOGO_DIMENSIONS_INVALID')}const ratio=Math.min(256/image.width,96/image.height,1);const w=Math.max(8,Math.ceil(image.width*ratio/8)*8),h=Math.max(1,Math.round(image.height*ratio));const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d')!;ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);ctx.drawImage(image,(w-image.width*ratio)/2,0,image.width*ratio,h);image.close();const pixels=ctx.getImageData(0,0,w,h).data;const bits=new Uint8Array(w*h/8);for(let i=0;i<w*h;i++)if(pixels[i*4]*.299+pixels[i*4+1]*.587+pixels[i*4+2]*.114<160)bits[Math.floor(i/8)]|=128>>(i%8);form.logo={width:w,height:h,bits:btoa(String.fromCharCode(...bits))}}catch(e){error.value=String(e)}}
function addKitchen(){form.kitchens.push({id:crypto.randomUUID(),name:'',categories:[]})}
function categoryText(k:Kitchen,event:Event){k.categories=[...new Set((event.target as HTMLInputElement).value.split(',').map(s=>s.trim()).filter(Boolean))]}
const amount=(value:number,currency:string,scale:number)=>new Intl.NumberFormat(locale.value==='id'?'id-ID':'en-US',{style:'currency',currency,minimumFractionDigits:scale,maximumFractionDigits:scale}).format(value/10**scale);
</script>
<template>
<Head :title="tr('POS Windows · Pengaturan','Windows POS · Settings')"/>
<main class="merch-page desktop-settings">
<header class="merch-heading"><div><p class="eyebrow">ONEQAY · BUSINESS WORKSPACE</p><h1>{{tr('Kasir yang siap melayani.','A checkout ready to serve.')}}</h1><p>{{tr('Kelola tim, identitas struk, dan operasional POS dari satu tempat.','Manage your team, receipt identity, and POS operations in one place.')}}</p></div><span class="ds-badge"><Icon name="monitor"/> Windows POS 0.2</span></header>
<div class="ds-summary"><div><Icon name="users"/><span>{{tr('Akun kasir aktif','Active cashiers')}}<strong>{{cashiers.filter(c=>c.enabled).length}}</strong></span></div><div><Icon name="printer"/><span>{{tr('Tujuan dapur','Kitchen destinations')}}<strong>{{form.kitchens.length}}</strong></span></div><div><Icon name="clock-3"/><span>{{tr('Menunggu pengesahan','Awaiting finalization')}}<strong>{{closures.length}}</strong></span></div></div>
<nav class="ds-tabs" aria-label="POS settings"><button v-for="item in tabs" :key="item.id" :class="{active:tab===item.id}" :aria-current="tab===item.id?'page':undefined" type="button" @click="tab=item.id"><Icon :name="item.icon" :size="18"/>{{item.name}}</button></nav>
<p v-if="error" class="ds-message error" role="alert">{{error}}</p><p v-if="success" class="ds-message" role="status">{{success}}</p>
<section v-if="tab==='receipt'" class="ds-columns"><form class="ds-card" @submit.prevent="save"><div class="ds-card-title"><Icon name="receipt-text"/><div><h2>{{tr('Identitas pada setiap struk','Your identity on every receipt')}}</h2><p>{{tr('Logo dicetak hanya pada bill pelanggan.','The logo appears only on customer bills.')}}</p></div></div><fieldset :disabled="busy"><label class="ds-check"><input v-model="form.show_logo" type="checkbox"/>{{tr('Tampilkan logo bisnis','Show the business logo')}}</label><label class="ds-upload"><Icon name="panels-top-left" :size="32"/><strong>{{tr('Unggah logo bisnis','Upload your business logo')}}</strong><span>PNG, JPG, WebP · 2 MB · {{tr('otomatis disesuaikan','automatically resized')}}</span><input type="file" accept="image/png,image/jpeg,image/webp" @change="upload"/></label><button v-if="form.logo" type="button" class="ds-link" @click="form.logo=null">{{tr('Hapus logo','Remove logo')}}</button><label>{{tr('Pesan di bagian bawah struk','Receipt footer')}}<textarea v-model="form.footer" rows="3" maxlength="240"/><small>{{form.footer.length}} / 240</small></label></fieldset><button class="ds-primary" :disabled="busy"><Icon name="check"/>{{tr('Simpan pengaturan','Save settings')}}</button></form><aside class="ds-preview"><span class="eyebrow">{{tr('PRATINJAU STRUK','RECEIPT PREVIEW')}}</span><div class="ds-paper"><img v-if="form.show_logo&&preview" :src="preview" alt="Logo"/><h3>{{tr('Nama bisnis Anda','Your business name')}}</h3><p>Kasir: Maya · 19/10/2026 09:41<br/>#desk-…8f17 · Meja 04</p><hr/><div><span>Kopi Susu × 2</span><b>30.000</b></div><div><span>Roti Panggang × 1</span><b>20.000</b></div><hr/><div><strong>TOTAL</strong><strong>50.000</strong></div><p class="ds-footer">{{form.footer}}</p></div><p>{{tr('Contoh tampilan. Harga dan mata uang mengikuti pengaturan bisnis. Logo maksimum 256 × 96 titik printer.','Display example. Prices and currency follow business settings. Logo maximum 256 × 96 printer dots.')}}</p></aside></section>
<section v-if="tab==='cashiers'" class="ds-card"><div class="ds-card-title"><div><h2>{{tr('Tim kasir','Cashier team')}}</h2><p>{{tr('Setiap petugas masuk dengan akun sendiri. PIN melindungi layar kasir.','Each cashier signs in with their own account. A PIN protects the checkout screen.')}}</p></div><button class="ds-primary" @click="edit()"><Icon name="plus"/>{{tr('Tambah kasir','Add cashier')}}</button></div><div class="ds-table"><table><thead><tr><th>{{tr('Petugas','Cashier')}}</th><th>Email</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="row in cashiers" :key="row.login"><td><strong>{{row.name}}</strong></td><td>{{row.login}}</td><td><span class="ds-badge" :class="{muted:!row.enabled}">{{row.enabled?tr('Aktif','Active'):tr('Nonaktif','Disabled')}}</span></td><td><button class="ds-link" @click="edit(row)">{{tr('Kelola akun','Manage account')}}</button></td></tr></tbody></table><div v-if="!cashiers.length" class="ds-empty"><Icon name="users" :size="36"/><h3>{{tr('Siapkan petugas pertama Anda.','Add your first cashier.')}}</h3><p>{{tr('Akun akan otomatis mendapat izin kasir untuk outlet ini.','The account receives cashier permissions for this outlet.')}}</p></div></div></section>
<section v-if="tab==='cashiers'&&owner_account" class="ds-card ds-owner"><Icon name="shield-check" :size="28"/><div><h2>{{tr('Owner juga bisa melayani di kasir.','Owners can serve at checkout too.')}}</h2><p>{{tr('Aktifkan akses POS dengan email dan kata sandi owner yang sama. Tidak perlu akun baru.','Enable POS access using your existing owner email and password. No additional account is needed.')}}</p></div><button class="ds-secondary" @click="editOwner">{{tr('Gunakan akun owner saya','Use my owner account')}}</button></section>
<section v-if="tab==='operations'" class="ds-columns"><form class="ds-card" @submit.prevent="save"><h2>{{tr('Keamanan & laporan shift','Security & shift reports')}}</h2><p>{{tr('Perubahan diterima perangkat saat terhubung kembali.','Devices receive changes when they reconnect.')}}</p><fieldset :disabled="busy"><label>{{tr('Kunci layar otomatis','Automatic screen lock')}}<select v-model.number="form.auto_lock_seconds"><option :value="0">{{tr('Nonaktif','Disabled')}}</option><option v-for="v in [60,120,300,900]" :key="v" :value="v">{{v/60}} {{tr('menit','minutes')}}</option></select></label><label>{{tr('Penerima laporan tutup kas','Shift report recipients')}}<textarea v-model="recipients" rows="5" placeholder="owner@example.com&#10;accounting@example.com"/><small>{{tr('Satu email per baris, maksimal 10. Laporan dikirim setelah sinkronisasi melalui antrean email platform.','One email per line, up to 10. Reports are queued for platform email delivery after synchronization.')}}</small></label></fieldset><button class="ds-primary" :disabled="busy"><Icon name="check"/>{{tr('Simpan pengaturan','Save settings')}}</button></form><aside class="ds-card"><Icon name="shield-check" :size="32"/><h2>{{tr('Pengesahan penutupan kas','Finalize cash closures')}}</h2><p>{{tr('Pengesah harus berbeda dari pembuka shift. Selisih kas mengikuti tinjauan rekonsiliasi di web.','The finalizer must differ from the shift opener. Cash variances follow the web reconciliation review.')}}</p><article v-for="c in closures" :key="c.operation_id" class="ds-closure"><strong>{{c.report.cashier}}</strong><code>{{c.report.shift_id}}</code><div>{{tr('Kas dihitung','Counted cash')}} <b>{{amount(c.report.counted,c.report.currency,c.report.scale)}}</b></div><div>{{tr('Selisih','Variance')}} <b>{{amount(c.report.variance,c.report.currency,c.report.scale)}}</b></div><button class="ds-primary" :disabled="busy" @click="finalize(c.operation_id)">{{tr('Sahkan penutupan','Finalize closure')}}</button></article><p v-if="!closures.length" class="ds-empty">{{tr('Tidak ada penutupan yang menunggu.','No closures waiting.')}}</p><a class="ds-link" href="/pos">{{tr('Buka ruang kerja rekonsiliasi','Open reconciliation workspace')}} →</a></aside></section>
<section v-if="tab==='kitchens'" class="ds-card"><div class="ds-card-title"><div><h2>{{tr('Pesanan langsung ke dapur yang tepat.','Orders reach the right kitchen.')}}</h2><p>{{tr('Cocokkan kategori produk, lalu pilih printer masing-masing dapur di POS Windows.','Match product categories, then select each kitchen printer in Windows POS.')}}</p></div><button class="ds-secondary" :disabled="form.kitchens.length>=12" @click="addKitchen"><Icon name="plus"/>{{tr('Tambah dapur','Add kitchen')}}</button></div><div v-for="(k,index) in form.kitchens" :key="k.id" class="ds-kitchen"><span class="ds-number">{{String(index+1).padStart(2,'0')}}</span><label>{{tr('Nama dapur','Kitchen name')}}<input v-model="k.name" required maxlength="48" placeholder="Dapur utama"/></label><label>{{tr('Kategori produk, pisahkan dengan koma','Product categories, separated by commas')}}<input :value="k.categories.join(', ')" @input="categoryText(k,$event)" placeholder="Makanan, Hidangan utama"/></label><button class="ds-link" :aria-label="tr('Hapus dapur','Remove kitchen')" @click="form.kitchens.splice(index,1)"><Icon name="x"/></button></div><div v-if="!form.kitchens.length" class="ds-empty"><Icon name="printer" :size="36"/><h3>{{tr('Tambahkan dapur atau bar.','Add a kitchen or bar.')}}</h3><p>{{tr('Bill dapur hemat kertas, tanpa harga dan logo.','Kitchen tickets use compact spacing, without prices or logos.')}}</p></div><button class="ds-primary" :disabled="busy" @click="save"><Icon name="check"/>{{tr('Simpan routing dapur','Save kitchen routing')}}</button></section>
<div v-if="editor" class="ds-overlay"><form class="ds-dialog" @submit.prevent="saveCashier"><div class="ds-card-title"><h2>{{cashier.version?tr('Kelola kasir','Manage cashier'):tr('Tambah akun kasir','Add cashier account')}}</h2><button type="button" class="ds-link" @click="!busy&&(editor=false)"><Icon name="x"/></button></div><p v-if="error" class="ds-message error" role="alert">{{error}}</p><p v-if="cashier.account_type==='owner'">{{tr('Gunakan password dan authenticator owner saat masuk POS. Buat PIN khusus untuk mengunci layar kasir.','Use your owner password and authenticator to sign in to POS. Set a PIN to lock the checkout screen.')}}</p><fieldset :disabled="busy"><label>{{tr('Nama petugas','Cashier name')}}<input v-model="cashier.name" required maxlength="96" autocomplete="name"/></label><label>Email<input v-model="cashier.login" :readonly="cashier.version>0||cashier.account_type==='owner'" required type="email" maxlength="190" autocomplete="off"/></label><label v-if="!cashier.version&&cashier.account_type!=='owner'">Password<input v-model="cashier.password" required type="password" minlength="12" maxlength="72" autocomplete="new-password"/></label><label>{{tr('PIN layar (6 angka)','Screen PIN (6 digits)')}}<input v-model="cashier.pin" :required="!cashier.version" type="password" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="new-password"/><small v-if="cashier.version">{{tr('Kosongkan untuk mempertahankan PIN saat ini.','Leave blank to keep the current PIN.')}}</small></label><label class="ds-check"><input v-model="cashier.enabled" type="checkbox"/>{{tr('Akun aktif','Account enabled')}}</label></fieldset><button class="ds-primary" :disabled="busy">{{tr('Simpan akun','Save account')}}</button></form></div>
</main>
</template>
