x solid #E9EBFF}.ds-empty{text-align:center;padding:38px;color:#3965FA}.ds-empty h3{font-size:15px;color:#3965FA;margin:14px 0 8px}.ds-empty p{margin:0}.ds-message{padding:13px 18px;border-radius:9px;background:#EDEDED;color:#3965FA;font-size:14px;overflow-wrap:anywhere}.ds-message.error{background:#EDEDED;color:#3965FA}.ds-kitchen{display:grid;grid-template-columns:40px 1fr 1.7fr 30px;align-items:center;gap:18px;border-bottom:1px solid #E9EBFF;padding:8px 0}.ds-number{color:#3965FA;font-size:22px;font-weight:700}.ds-closure{border:1px solid #E9EBFF;padding:18px;border-radius:10px;margin:20px 0;font-size:14px}.ds-closure code{display:block;color:#3965FA;margin:6px 0;font-size:14px}.ds-closure>div{display:flex;justify-content:space-between;padding:8px 0}.ds-closure button{margin-top:14px}.ds-overlay{position:fixed;inset:0;z-index:200;background:#1B1B3959;display:grid;place-items:center;padding:20px}.ds-dialog{background:var(--oq-white);border-radius:18px;padding:28px;width:460px;max-width:100%;max-height:90vh;overflow:auto}.ds-dialog h2{font-size:20px}.ds-dialog>.ds-primary{width:100%}@media(max-width:900px){.ds-columns{grid-template-columns:1fr}.ds-summary{gap:8px}.ds-summary>div{padding:14px}.ds-tabs{overflow:auto}.merch-page .ds-tabs button{white-space:nowrap}.ds-kitchen{grid-template-columns:30px 1fr 1fr 25px}.ds-card{padding:20px}}

.ds-owner{display:flex;align-items:center;flex-wrap:wrap;gap:20px;margin-top:20px}.ds-owner>div{flex:1;min-width:220px}.ds-owner p{margin:0}
/* Proportional configuration controls with solid, seven-color states. */
.ds-summary>div,.ds-card,.ds-preview{border:1px solid var(--oq-light);border-radius:16px;background:var(--oq-white);box-shadow:var(--oq-shadow)}
.ds-summary>div{color:var(--oq-primary)}.ds-summary span,.ds-card p,.ds-card small,.ds-preview>p{color:var(--oq-navy);font-size:.875rem}
