.ds-primary,.merch-page .ds-primary{background:var(--oq-primary)!important;color:var(--oq-white)!important;border:1px solid var(--oq-primary)!important;font-size:.875rem;min-height:44px}
.ds-secondary,.merch-page .ds-secondary{background:var(--oq-pale)!important;color:var(--oq-navy)!important;border:1px solid var(--oq-soft)!important;font-size:.875rem;min-height:44px}
.ds-link{color:var(--oq-navy);font-size:.875rem;text-decoration:underline;text-underline-offset:3px}
